// civ_hero_aura_table() rows a finished structure of this BuildingType projects
// (0 A.D. structures/<civ>/*.xml Auras), ending in -1.
inline const int16_t *civ_building_auras(uint8_t type) {
	static const int16_t kNone[1] = {-1};
	switch (type) {
		case BLD_MONUMENT: { static const int16_t k[2] = {100, -1}; return k; }
		case BLD_PILLAR: { static const int16_t k[2] = {101, -1}; return k; }
		case BLD_PYRAMID_LARGE: { static const int16_t k[3] = {102, 103, -1}; return k; }
		case BLD_PYRAMID_SMALL: { static const int16_t k[2] = {104, -1}; return k; }
		case BLD_TEMPLE_AMUN: { static const int16_t k[3] = {106, 109, -1}; return k; }
		case BLD_TEMPLE_VESTA: { static const int16_t k[2] = {105, -1}; return k; }
		case BLD_TEMPLE_MARS: { static const int16_t k[2] = {105, -1}; return k; }
		case BLD_KUSH_SHRINE: { static const int16_t k[2] = {105, -1}; return k; }
		case BLD_TEMPLE_ISIS: { static const int16_t k[2] = {105, -1}; return k; }
		default: return kNone;
	}
}

