// Each civ's 0 A.D. bonuses as one line of text for the civ picker.
inline const char *civ_bonus_text(uint8_t civ) {
	static const char *kText[CIV_COUNT] = {
		"Silver Owls: Workers +10% metal gather rate per phase advance. Epilektoi Infantry: Elite Hoplites can promote to Champion Spearmen. Delian League: Ships −25% construction time. Hellenic Architecture: Structures +10% health and +10% capture points.",
		"Ritualistic Exercise: Citizen-Soldiers +40% health and +50% melee attack hack damage. Laws of Lycurgus: Champion Hoplites are available in village phase, and can promote to highly experienced Olympic Champions. Agoge: Champion Hoplites -10% attack time. Hellenic Architecture: Structures +10% health and +10% capture points.",
		"Darics: Land Traders +25% trade gain. Large Rams: Battering Rams +20% attack damage and +2 garrison capacity. Times of War: The batch training time of units trained in Stables decreases each phase advance. Satrapy Tribute: Upgrade the Throne Hall to receive a free trickle of a desired resource. Great King's Levy: +10% maximum population limit.",
		"Fertility: Women train from houses without the need to research Fertility Festival. Testudo Formation: Roman Legionaries can form a Testudo. Centurions: Promote Elite Rank Spearmen or Swordsmen to Champion Centurions. Legionary Engineers: Siege Catapults and Onagers 10% faster fire rate and +20% movement speed.",
		"Trademasters: Trade ships are available in the Village Phase. Mining Economy: Stone mining technologies are free and instant. Numidian Cavalry: Cavalry Javelineers +10% walk speed. Servants: Workers +25% stone gather rate. Servants: Workers +25% stone gather rate. Servants: Workers +25% stone gather rate. Triple Walls: City Walls +200% health, but +100% build time and stone cost.",
		"Hellenic Architecture: Structures +10% health and +10% capture points. Resource-Rich Economy: Storehouse technologies −100% research time.",
		"Deas Celtica: Druids increase attack rates of soldiers near them by 5%. Woad Warriors: All Infantry Units +5% movement speed, and gain +1 loot taking. Wooden Construction: Structures −20% build time, −20% health, and −20% capture points.",
		"Deas Celtica: Druids increase attack rates of soldiers near them by 5%. Wooden Construction: Structures −20% build time, −20% health, and −20% capture points. Superior Cavalry: Cavalry +10% melee attack damage.",
		"Starting Walls: Iberians start with City Walls around their base on most maps. Massive Towers: Stone Towers −50% wood cost, +150% stone cost, +33% build time, +60% health, +3 garrison capacity, and +1 default arrow count.",
		"Elephant Tradition: Elephants −30% training time. Emperor of Emperors: +10% maximum population limit. Wooden Walls: City Walls −20% build time and −20% health.",
		"Large Rams: Battering Rams +20% attack damage and +2 garrison capacity.",
		"Polybolos: Bolt Shooters −45% attack damage and −50% attack time. Nile Delta: The three farming technologies are available in Village Phase. Sun-dried Mud Bricks: Houses and Economic Structures −40% wood cost, health, and capture points as well as +50% build time.",
		"Fertile Crescent: Farms −25% wood cost and −75% build time.",
		"Federated States: +10% maximum population limit. Great Wall: City Walls +50% health.",
		"", // CIV_GAIA
		"Seeresses: A unique Champion Healer unit is available in City Phase. Bovine Tradition: Civilians +100% meat gather rate. Cimbrian Caravans: Civilians +0.5 movement speed.",
	};
	return kText[civ < CIV_COUNT ? civ : 0];
}

// [first, last) rows of civ_unit_template_table() for each civ. Rows from
// CIV_ROSTER_PROMOTION_ONLY_FIRST on are units no structure trains, reached only by
// promotion (0 A.D. Promotion/Entity), after every civ's block so that adding one
// never moves a trainable row's template id. Trainable rows added later follow them
// (template ids never move); civ_roster_ids() gives a civ's block and its added rows.
inline constexpr uint16_t CIV_ROSTER_PROMOTION_ONLY_FIRST = 372;
inline const uint16_t *civ_roster_offsets() {
	static const uint16_t kOffsets[CIV_COUNT + 1] = {0, 28, 50, 76, 107, 137, 164, 186, 209, 231, 256, 285, 315, 345, 372, 372, 372};
	return kOffsets;
}

